theorem antipode_gen_mem :
    HopfAlgebra.antipode R ((ι R R 1 : SymmetricAlgebra R R) ^ p) ∈
      Ideal.span {(ι R R 1 : SymmetricAlgebra R R) ^ p}

def inclusion :
    WithConv (CoordinateRing (R := R) p →ₐ[R] A) →*
      WithConv (SymmetricAlgebra R R →ₐ[R] A)

def charPoints (m : M) :
    WithConv (MonoidAlgebra R M →ₐ[R] A) →*
      WithConv (MonoidAlgebra R (Multiplicative ℤ) →ₐ[R] A)

def cocharPoints (ψ : M →* Multiplicative ℤ) :
    WithConv (MonoidAlgebra R (Multiplicative ℤ) →ₐ[R] A) →*
      WithConv (MonoidAlgebra R M →ₐ[R] A)

def powEnd (n : ℤ) :
    WithConv (MonoidAlgebra R (Multiplicative ℤ) →ₐ[R] A) →*
      WithConv (MonoidAlgebra R (Multiplicative ℤ) →ₐ[R] A)

lemma baseChangeMap_apply_tmul {H L : _root_.CommHopfAlgCat.{v} k}
    (φ : H ⟶ L) (s : K) (h : H) :
    (baseChangeMap (K := K) φ).hom (s ⊗ₜ[k] h) = s ⊗ₜ[k] φ.hom h

def mapPointsFunctor {H K : CommHopfAlgCat.{v} R} (φ : H ⟶ K) :
    HopfAlgebra.pointsFunctor (R := R) (H := K) ⟶
      HopfAlgebra.pointsFunctor (R := R) (H := H)

lemma mapPointsFunctor_app_injective_of_surjective {H K : CommHopfAlgCat.{v} R}
    (φ : H ⟶ K) (hφ : Function.Surjective φ.hom) (A : CommAlgCat.{w} R) :
    Function.Injective ((mapPointsFunctor φ).app A)

lemma baseChangeMap_apply_tmul {H L : FiniteTypeCommHopfAlgCat.{u, v} k}
    (φ : H ⟶ L) (s : K) (h : H) :
    toBialgHom (baseChangeMap (K := K) φ) (s ⊗ₜ[k] h) = s ⊗ₜ[k] toBialgHom φ h

lemma toBialgHom_comp {H K L : FiniteTypeCommHopfAlgCat.{u, v} R}
    (φ : H ⟶ K) (ψ : K ⟶ L) :
    toBialgHom (φ ≫ ψ) = (toBialgHom ψ).comp (toBialgHom φ)

def pointsMulEquiv (H K : FiniteTypeCommHopfAlgCat.{u, v} R) :
    HopfAlgebra.points (R := R) (H := tensorProduct H K) A ≃*
      HopfAlgebra.points (R := R) (H := H) A × HopfAlgebra.points (R := R) (H := K) A

def prodPointsMulEquiv :
    WithConv (MonoidAlgebra R (G × H) →ₐ[R] A) ≃*
      WithConv (MonoidAlgebra R G →ₐ[R] A) × WithConv (MonoidAlgebra R H →ₐ[R] A)

def prodPointsMulEquiv :
    WithConv (MonoidAlgebra R (G' × H') →ₐ[R] A) ≃*
      WithConv (MonoidAlgebra R G' →ₐ[R] A) × WithConv (MonoidAlgebra R H' →ₐ[R] A)

def quotientKerPointsMulEquiv (f : H →ₐc[R] K)
    (hf : Function.Surjective f) (A : CommAlgCat.{x} R) :
    WithConv (H ⧸ (ker f hf).toIdeal →ₐ[R] A) ≃* WithConv (K →ₐ[R] A)

def quotientPointsSubgroup (H : _root_.CommHopfAlgCat.{v} R)
    (I : HopfIdeal R H) (A : CommAlgCat.{w} R) :
    Subgroup (HopfAlgebra.points (R := R) (H := H) A)

lemma mapPoints_mem_quotientPointsSubgroup (H : _root_.CommHopfAlgCat.{v} R)
    (I : HopfIdeal R H) {A B : CommAlgCat.{w} R}
    (χ : A ⟶ B) {g : HopfAlgebra.points (R := R) (H := H) A}
    (hg : g ∈ quotientPointsSubgroup H I A) :
    HopfAlgebra.mapPoints (H := H) χ g ∈ quotientPointsSubgroup H I B

def mapQuotientPointsSubgroup (H : _root_.CommHopfAlgCat.{v} R)
    (I : HopfIdeal R H) {A B : CommAlgCat.{w} R}
    (χ : A ⟶ B) :
    quotientPointsSubgroup H I A →* quotientPointsSubgroup H I B

def quotientPointsSubgroupFunctor
    (H : _root_.CommHopfAlgCat.{v} R) (I : HopfIdeal R H) :
    CommAlgCat.{w} R ⥤ GrpCat.{max v w}

def liftQuotientPointHom (H : _root_.CommHopfAlgCat.{v} R)
    (I : HopfIdeal R H) (A : CommAlgCat.{w} R) :
    quotientPointsSubgroup H I A →* HopfAlgebra.points (R := R) (H := quotient H I) A

def restrictHom :
    WithConv ((H₁ ⊗[R] H₂) →ₐ[R] A) →*
      WithConv (H₁ →ₐ[R] A) × WithConv (H₂ →ₐ[R] A)

def baseChangePointsMulEquiv (n : ℕ) :
    WithConv (K ⊗[k] MonoidAlgebra k (Multiplicative (ZMod n)) →ₐ[K] A) ≃*
      rootsOfUnity n A

def pointsMulEquiv (n : ℕ) :
    WithConv (MonoidAlgebra R (Multiplicative (ZMod n)) →ₐ[R] A) ≃*
      rootsOfUnity n A

def inclusion (n : ℕ) :
    WithConv (MonoidAlgebra R (Multiplicative (ZMod n)) →ₐ[R] A) →*
      WithConv (MonoidAlgebra R (Multiplicative ℤ) →ₐ[R] A)

def latticePairing :
    (σ →₀ ℤ) →ₗ[ℤ]
      Additive (Multiplicative (σ →₀ ℤ) →* Multiplicative ℤ) →ₗ[ℤ] ℤ

theorem eq_one_of_forall_pairing_eq_zero {ψ : Multiplicative (σ →₀ ℤ) →* Multiplicative ℤ}
    (h : ∀ m : σ →₀ ℤ, DiagonalizableGroup.pairing (Multiplicative.ofAdd m) ψ = 0) :
    ψ = 1

abbrev restrictScalarsMap {A B : _root_.CommAlgCat.{x} K}
    (f : k →+* K) (χ : A ⟶ B) :
    restrictScalarsObj f A ⟶ restrictScalarsObj f B

theorem LocalGeneratorsData.IsInvertible.ofIso {q : SheafOfModules.LocalGeneratorsData M}
    (hq : LocalGeneratorsData.IsInvertible q) (e : M ≅ N) :
    LocalGeneratorsData.IsInvertible (LocalGeneratorsData.ofIso q e)

def trivializationIso {q : SheafOfModules.LocalGeneratorsData M}
    (hq : LocalGeneratorsData.IsInvertible q) (i : q.I) :
    _root_.SheafOfModules.free (R := R.over (q.X i)) PUnit ≅ M.over (q.X i)

theorem isoOfLinearEquiv_hom_toLinearMap {M N : ComoduleCat.{u, v, w} R C}
    (e : M ≃ₗ[R] N) (h) :
    ((isoOfLinearEquiv (R := R) (C := C) e h).hom).toLinearMap = e.toLinearMap

theorem isoOfLinearEquiv_hom_apply {M N : ComoduleCat.{u, v, w} R C}
    (e : M ≃ₗ[R] N) (h) (m : M) :
    (isoOfLinearEquiv (R := R) (C := C) e h).hom m = e m

theorem isoOfLinearEquiv_inv_apply {M N : ComoduleCat.{u, v, w} R C}
    (e : M ≃ₗ[R] N) (h) (n : N) :
    (isoOfLinearEquiv (R := R) (C := C) e h).inv n = e.symm n

theorem corestrict_map_toLinearMap (f : C →ₗc[R] D) {M N : ComoduleCat.{u, v, x} R C}
    (g : M ⟶ N) :
    ((corestrict (R := R) (C := C) (D := D) f).map g).toLinearMap = g.toLinearMap

theorem corestrict_map_apply (f : C →ₗc[R] D) {M N : ComoduleCat.{u, v, x} R C}
    (g : M ⟶ N) (m : M) :
    (corestrict (R := R) (C := C) (D := D) f).map g m = g m

theorem corestrict_map_apply (f : C →ₗc[R] D) {M N : FGComoduleCat.{u, v, x} R C}
    (g : M ⟶ N) (m : M) :
    (corestrict (R := R) (C := C) (D := D) f).map g m = g m

theorem prod_hom_ext {P M N : FGComoduleCat.{u, v, w} R C} {f g : P ⟶ prod R C M N}
    (hfst : f ≫ prodFst M N = g ≫ prodFst M N)
    (hsnd : f ≫ prodSnd M N = g ≫ prodSnd M N) : f = g

def tensorBifunctor :
    FGComoduleCat.{u, v, w} R C × FGComoduleCat.{u, v, w} R C ⥤
      FGComoduleCat.{u, v, w} R C

theorem matrixCoefficientSubmodule_le {P : Submodule R C}
    (hP : ∀ (φ : M →ₗ[R] R) (m : M), matrixCoefficient (R := R) (C := C) φ m ∈ P) :
    matrixCoefficientSubmodule (R := R) (C := C) (M := M) ≤ P

theorem matrixCoefficientSubalgebra_le {S : Subalgebra R C}
    (hS : ∀ (φ : M →ₗ[R] R) (m : M), matrixCoefficient (R := R) (C := C) φ m ∈ S) :
    matrixCoefficientSubalgebra (R := R) (C := C) (M := M) ≤ S

theorem prod_hom_ext {P M N : ComoduleCat.{u, v, w} R C} {f g : P ⟶ prod R C M N}
    (hfst : f ≫ prodFst M N = g ≫ prodFst M N)
    (hsnd : f ≫ prodSnd M N = g ≫ prodSnd M N) : f = g

theorem prod_hom_ext' {M N P : ComoduleCat.{u, v, w} R C} {f g : prod R C M N ⟶ P}
    (hinl : prodInl M N ≫ f = prodInl M N ≫ g)
    (hinr : prodInr M N ≫ f = prodInr M N ≫ g) : f = g

theorem groupLike_mem_groupLikeSetSpan {s : Set (GroupLike R C)} {g : GroupLike R C}
    (hg : g ∈ s) :
    (g : C) ∈ groupLikeSetSpan (R := R) (C := C) s

theorem map_le_iff {A : Subcomodule R C M} {f : Comodule.Hom R C M N}
    {B : Subcomodule R C N} :
    A.map f ≤ B ↔ ∀ ⦃m⦄, m ∈ A → f m ∈ B

theorem rTensor_rangeRestrict_eq_zero_of_rTensor_eq_zero
    {M₁ : Type w} {N₁ : Type x}
    [AddCommGroup M₁] [Module R M₁] [AddCommGroup N₁] [Module R N₁]
    {B : Submodule R N₁} {f : M₁ →ₗ[R] N₁} {t : M₁ ⊗[R] C}
    (h : LinearMap.rTensor C (B.mkQ.comp f) t = 0) :
    LinearMap.rTensor C (B.mkQ.comp f).rangeRestrict t = 0

theorem map_le_iff_le_comap {A : Subcomodule R C M} {B : Subcomodule R C N}
    {f : Comodule.Hom R C M N} :
    A.map f ≤ B ↔ A ≤ B.comap f

def elementaryTwoQuotientLiftEquiv [AddMonoid M] :
    (ElementaryTwoQuotient G →+ M) ≃
      {φ : Additive G →+ M // ∀ g, 2 • φ g = 0}

def elementaryTwoQuotientLinearLiftEquiv [AddCommGroup H] [Module (ZMod 2) H] :
    (ElementaryTwoQuotient G →ₗ[ZMod 2] H) ≃
      {φ : Additive G →+ H // ∀ g, 2 • φ g = 0}

theorem card_elementaryTwoQuotient_eq_card_twoTorsion
    [(powMonoidHom 2 : G →* G).ker.FiniteIndex] :
    Nat.card (ElementaryTwoQuotient G) = Nat.card {g : G // g ^ 2 = 1}

def elementaryTwoQuotientProdAddEquiv :
    ElementaryTwoQuotient (G × H) ≃+
      ElementaryTwoQuotient G × ElementaryTwoQuotient H

def elementaryTwoQuotientProdLinearEquiv (G H : Type*) [CommGroup G] [CommGroup H] :
    ElementaryTwoQuotient (G × H) ≃ₗ[ZMod 2]
      ElementaryTwoQuotient G × ElementaryTwoQuotient H

theorem finite_compl_fixedBy_conj {G α : Type*} [Group G] [MulAction G α] {g h : G}
    (hh : (MulAction.fixedBy α h)ᶜ.Finite) :
    (MulAction.fixedBy α (g⁻¹ * h * g))ᶜ.Finite

def normalizerOrbitRelQuotientMap (H : Subgroup G)
    (g : _root_.Subgroup.normalizer (H : Set G)) :
    _root_.MulAction.orbitRel.Quotient H X → _root_.MulAction.orbitRel.Quotient H X

def normalizerOrbitRelQuotientEquiv (H : Subgroup G)
    (g : _root_.Subgroup.normalizer (H : Set G)) :
    Equiv.Perm (_root_.MulAction.orbitRel.Quotient H X)

def normalizerOrbitRelQuotientPermHom (H : Subgroup G) :
    _root_.Subgroup.normalizer (H : Set G) →*
      Equiv.Perm (_root_.MulAction.orbitRel.Quotient H X)

def normalizerQuotientOrbitRelQuotientPermHom (H : Subgroup G) :
    Subgroup.normalizerQuotient H →*
      Equiv.Perm (_root_.MulAction.orbitRel.Quotient H X)

theorem le_of_comap_le_comap_of_surjective (f : H →ₐc[R] K)
    (hf : Function.Surjective f) {I J : HopfIdeal R K}
    (hIJ : I.comap f hf ≤ J.comap f hf) : I ≤ J

theorem setOf_abs_intCoeff_le_eq (d B : ℕ) :
    {f : ℤ[X] | f.natDegree ≤ d ∧ ∀ i, |f.coeff i| ≤ (B : ℤ)} =
      {f : ℤ[X] | f.natDegree ≤ d ∧ ∀ i, f.coeff i ∈ Finset.Icc (-(B : ℤ)) B}
